/**
 * ctzb-dashboard — the ETH Setup Standard dashboard, served from Cloudflare.
 *
 * GENERATED by cloudflare/build_dashboard.py from docs/artifacts/eth-setup-standard.html
 * (the page) and cloudflare/dashboard_shim.js (a stand-in for the Dashboard artifact
 * type's runtime). Edit those, then rebuild. Do not edit this file by hand.
 *
 * Replaces a Claude scheduled task that uploaded every CSV to a claude.ai artifact six
 * times a day (item 17f). The page reads the pipeline's datasets live, through this
 * Worker, from the ctzb-feed mirror over a Service Binding -- Worker to Worker, no
 * public hop -- so the mirror can later be locked down without breaking this page.
 *
 * Also sends Jared's phone alerts through a private Telegram bot (replacing the same
 * scheduled task's notifications): on its cron it reads the feed's `alerts` list (feed
 * schema 4, item 17d) and sends each alert_id once, ever, recording it in KV.
 *
 * Bindings:
 *   MIRROR              Service Binding -> the ctzb-feed Worker
 *   NOTIFY              KV namespace (alerts already sent; notifier status; heartbeat).
 *                       ctzb-scheduler binds the same namespace to watch the heartbeat.
 *   TELEGRAM_BOT_TOKEN  secret: the bot's token from @BotFather
 *   TELEGRAM_CHAT_ID    plain var: Jared's numeric Telegram id (the first recipient)
 *   TELEGRAM_EXTRA_CHAT_IDS  optional plain var (27 Nov 2026): more numeric Telegram ids, comma-separated, that get
 *                       the same setup alerts (Joe). Each must have pressed Start on the bot. Outage alerts
 *                       (ctzb-scheduler) are not affected and stay with Jared.
 *   GATE_MODE           plain var: "access" (Cloudflare Access) or "password"
 *   ACCESS_TEAM_DOMAIN  plain var, access mode: e.g. "ethkros.cloudflareaccess.com"
 *   ACCESS_AUD          plain var, access mode: the Access application's AUD tag
 *   DASHBOARD_PASSWORD  secret, password mode only
 *
 * THE GATE FAILS CLOSED. Every path, /health included, is refused unless the configured
 * gate passes, and an unset or unknown GATE_MODE refuses everything. In access mode the
 * Access JWT's signature, audience, issuer and expiry are all verified here, so turning
 * Access off by mistake -- or reaching the Worker by a preview URL that Access does not
 * cover -- still gets nothing.
 */

const PAGE = __PAGE__;
const DATASET = /^\/data\/datasets\/([a-z0-9_]{1,64}\.csv)$/;
const CERT_TTL_MS = 60 * 60 * 1000;
let certCache = { at: 0, team: "", keys: [] };

const SEC_HEADERS = {
  "x-content-type-options": "nosniff",
  "referrer-policy": "no-referrer",
  "x-frame-options": "DENY",
};
const PAGE_CSP =
  "default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; " +
  "connect-src 'self'; img-src 'self' data:; font-src 'self' data:; base-uri 'none'; " +
  "form-action 'none'; frame-ancestors 'none'";

async function cardsCleared(env) {
  try {
    const r = await env.MIRROR.fetch(new Request("https://mirror/feed/ctzb_feed.json"));
    if (!r.ok) return false;
    const f = await r.json();
    return f && f.cards_withheld === false;
  } catch (_) { return false; }
}

function deny(status, msg, extra) {
  return new Response(msg, {
    status,
    headers: { "content-type": "text/plain; charset=utf-8", "cache-control": "no-store", ...SEC_HEADERS, ...(extra || {}) },
  });
}

/* ---------- base64url / JWT ---------- */
function b64urlToBytes(s) {
  s = s.replace(/-/g, "+").replace(/_/g, "/");
  while (s.length % 4) s += "=";
  const bin = atob(s);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
const b64urlJSON = (s) => JSON.parse(new TextDecoder().decode(b64urlToBytes(s)));

async function accessKeys(team, fetchImpl) {
  const now = Date.now();
  if (certCache.team === team && now - certCache.at < CERT_TTL_MS && certCache.keys.length) return certCache.keys;
  const res = await fetchImpl(`https://${team}/cdn-cgi/access/certs`);
  if (!res.ok) throw new Error("certs " + res.status);
  const j = await res.json();
  certCache = { at: now, team, keys: Array.isArray(j.keys) ? j.keys : [] };
  return certCache.keys;
}

/** True only for a token Cloudflare Access issued for THIS application, unexpired. */
async function verifyAccessJwt(token, env, fetchImpl = fetch, nowSec = Math.floor(Date.now() / 1000)) {
  const team = env.ACCESS_TEAM_DOMAIN, aud = env.ACCESS_AUD;
  if (!token || !team || !aud) return false;
  const parts = token.split(".");
  if (parts.length !== 3) return false;
  let header, payload;
  try { header = b64urlJSON(parts[0]); payload = b64urlJSON(parts[1]); } catch (_) { return false; }
  if (header.alg !== "RS256" || !header.kid) return false;
  let keys;
  try { keys = await accessKeys(team, fetchImpl); } catch (_) { return false; }
  const jwk = keys.find((k) => k.kid === header.kid);
  if (!jwk) return false;
  let ok = false;
  try {
    const key = await crypto.subtle.importKey("jwk", { kty: jwk.kty, n: jwk.n, e: jwk.e, alg: "RS256", ext: true },
      { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" }, false, ["verify"]);
    ok = await crypto.subtle.verify("RSASSA-PKCS1-v1_5", key, b64urlToBytes(parts[2]),
      new TextEncoder().encode(parts[0] + "." + parts[1]));
  } catch (_) { return false; }
  if (!ok) return false;
  const auds = Array.isArray(payload.aud) ? payload.aud : [payload.aud];
  if (!auds.includes(aud)) return false;
  if (payload.iss !== `https://${team}`) return false;
  if (typeof payload.exp !== "number" || payload.exp <= nowSec) return false;
  if (typeof payload.nbf === "number" && payload.nbf > nowSec + 60) return false;
  return true;
}

/* ---------- password mode ---------- */
async function sameSecret(a, b) {
  // Compare digests in constant time, so the comparison leaks neither content nor length.
  const enc = new TextEncoder();
  const [x, y] = await Promise.all([crypto.subtle.digest("SHA-256", enc.encode(a)), crypto.subtle.digest("SHA-256", enc.encode(b))]);
  const u = new Uint8Array(x), v = new Uint8Array(y);
  let diff = 0;
  for (let i = 0; i < u.length; i++) diff |= u[i] ^ v[i];
  return diff === 0;
}

async function passwordOk(req, env) {
  const want = env.DASHBOARD_PASSWORD;
  if (!want) return false;
  const h = req.headers.get("authorization") || "";
  if (!h.startsWith("Basic ")) return false;
  let decoded = "";
  try { decoded = atob(h.slice(6)); } catch (_) { return false; }
  const pw = decoded.slice(decoded.indexOf(":") + 1);
  return sameSecret(pw, want);
}

/** null when the request may proceed; otherwise the refusal to send. */
async function gate(req, env, fetchImpl = fetch) {
  if (env.GATE_MODE === "access") {
    const ok = await verifyAccessJwt(req.headers.get("cf-access-jwt-assertion"), env, fetchImpl);
    return ok ? null : deny(403, "Forbidden");
  }
  if (env.GATE_MODE === "password") {
    return (await passwordOk(req, env)) ? null
      : deny(401, "Login required", { "www-authenticate": 'Basic realm="ETH Setup Standard", charset="UTF-8"' });
  }
  return deny(503, "Dashboard gate not configured");   // fail closed
}

/* ---------- Telegram alerts ---------- */
const NUM = (v, d = 1) => (v === null || v === undefined || v === "" || isNaN(+v)) ? null : (+v).toFixed(d);
const PCT = (v) => NUM(v, 0) === null ? "n/a" : NUM(v, 0) + "%";
// 27 Nov 2026 (Jared): one plain format, the same four parts as the member card. What and when (with the price line),
// one label (Top grade = grade A+, the site's own test; no letter shown), one number (the card's "rose 10% within 60
// days" with its sample size) and one risk number (the card's typical drop from entry). Letters, lens codes, bucket
// and diamond tags, the 25.3% and +20% figures stay on the dashboard. Replaces the 26 Nov wording ("Bucket A · ...").
const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const DAYW = (iso) => { const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(iso || "")); return m ? `${+m[3]} ${MONTHS[+m[2] - 1]} ${m[1]}` : String(iso || "?"); };
const PRICE = (v) => { const t = NUM(v, 2); if (t === null) return "?"; const [i, d] = t.split("."); return i.replace(/\B(?=(\d{3})+(?!\d))/g, ",") + "." + d; };
const SIGNED = (v) => { const t = NUM(v, 1); return t === null ? null : (+t < 0 ? "−" + t.slice(1) : "+" + t) + "%"; };
function chartName(chart) {
  const m = /^(ETH|BTC) (\d+)D$/.exec(String(chart || ""));
  return m ? `${m[1]} · ${m[2]}-day chart` : String(chart || "?");
}
const topLabel = (grade) => grade === "A+" ? "TOP GRADE" : "Not top grade";
function oddsLines(card, asset) {
  if (!card || card.rose10_within60d_pct == null || !card.past_trades) return ["Odds not available"];
  const pooled = / across the /.test(String(card.sample || ""));
  const of = pooled ? `${card.past_trades} past ${asset} signals across its 1- to 5-day charts` : `${card.past_trades} past signals`;
  const out = [`${PCT(card.rose10_within60d_pct)} of ${of} rose 10% within 60 days`];
  const dip = SIGNED(card.typical_deepest_dip_pct);
  if (dip) out.push(`Typical drop from entry: ${dip}`);
  return out;
}

function alertText(a, feed) {
  const card = (feed.cards || []).find((c) => c.signal_id === a.signal_id);
  const print = (feed.prints || []).find((p) => p.signal_id === a.signal_id);
  const open = (feed.open_signals || []).find((o) => o.signal_id === a.signal_id);
  const asset = String(a.chart || "").split(" ")[0];
  const lines = [];
  if (a.event === "forming") {
    lines.push(`FORMING · ${chartName(a.chart)}`);
    if (card) {
      lines.push(`Confirms ${DAYW(card.confirms_on)}` + (card.must_close_above != null ? ` if it closes above ${PRICE(card.must_close_above)}` : "") + ". It can still vanish.");
      lines.push(topLabel(card.grade), ...oddsLines(card, asset));
    } else {
      lines.push("Not confirmed yet. It can still vanish.");
    }
  } else if (a.event === "confirmed") {
    lines.push(`CONFIRMED · ${chartName(a.chart)}`);
    const when = (open && open.entry_date) || (print && print.confirms_on);
    const px = (open && open.entry_close) ?? (print && print.entry_close);
    if (when) lines.push(`Entry: close ${px != null ? PRICE(px) : "?"} on ${DAYW(when)}`);
    if (open) lines.push(topLabel(open.grade), ...oddsLines(open.card, asset));
  } else if (a.event === "vanished") {
    lines.push(`VANISHED · ${chartName(a.chart)}`);
    lines.push("The forming low didn't confirm.");
  } else {
    lines.push(`${String(a.event).toUpperCase()} · ${chartName(a.chart)}`);
  }
  lines.push("", "Computed signal, not a trade. Entry quality only.");
  return lines.join("\n");
}

/** The ONLY place the bot token is used. Returns the HTTP status; never the body. */
/** Every recipient: Jared first, then TELEGRAM_EXTRA_CHAT_IDS. Only numeric ids (a group or channel id may start with -). */
function recipients(env) {
  const extra = String(env.TELEGRAM_EXTRA_CHAT_IDS || "").split(",").map((s) => s.trim()).filter((s) => /^-?\d{5,20}$/.test(s));
  return [String(env.TELEGRAM_CHAT_ID)].concat(extra.filter((x, i) => x !== String(env.TELEGRAM_CHAT_ID) && extra.indexOf(x) === i));
}
// Jared's key stays "sent:<alert>" (as before 27 Nov 2026); another recipient's is "sent:<alert>@<id>"
const sentKey = (alertId, chat, i) => i === 0 ? "sent:" + alertId : "sent:" + alertId + "@" + chat;

async function telegramSend(env, text, fetchImpl, chatId = env.TELEGRAM_CHAT_ID) {
  const r = await fetchImpl(`https://api.telegram.org/bot${env.TELEGRAM_BOT_TOKEN}/sendMessage`, {
    method: "POST", headers: { "content-type": "application/json" },
    body: JSON.stringify({ chat_id: chatId, text, disable_web_page_preview: true }),
  });
  return r.status;
}

/** One pass: send every alert in the current feed that has not been sent before. */
async function notify(env, fetchImpl = fetch) {
  if (!env.NOTIFY || !env.MIRROR || !env.TELEGRAM_BOT_TOKEN || !env.TELEGRAM_CHAT_ID) return { skipped: "not configured" };
  let feed;
  try {
    const r = await env.MIRROR.fetch(new Request("https://mirror/feed/ctzb_feed.json"));
    if (!r.ok) return { skipped: "feed " + r.status };
    feed = await r.json();
  } catch (_) { return { skipped: "feed unreadable" }; }
  if (feed.alerts_withheld) return { skipped: "withheld" };
  let sent = 0, failed = 0, lastStatus = null;
  const to = recipients(env);
  for (const a of feed.alerts || []) {
    if (!a || !a.alert_id) continue;
    for (let i = 0; i < to.length; i++) {
      // each recipient is recorded on its own, so a failure for one never resends to another
      const key = sentKey(a.alert_id, to[i], i);
      if (await env.NOTIFY.get(key)) continue;
      let status = 0;
      try { status = await telegramSend(env, alertText(a, feed), fetchImpl, to[i]); } catch (_) { status = 0; }
      lastStatus = status;
      if (status === 200) {
        // Remember for a year. The feed carries an alert for at least 24 hours (feed_live.py ALERT_HOLD_HOURS), so this is ample.
        await env.NOTIFY.put(key, String(Date.now()), { expirationTtl: 365 * 86400 });
        sent++;
      } else failed++;   // not recorded: the next tick retries it
    }
  }
  if (sent || failed) {
    const prev = (await env.NOTIFY.get("status", { type: "json" })) || {};
    await env.NOTIFY.put("status", JSON.stringify({
      last_sent_at: sent ? new Date().toISOString() : prev.last_sent_at || null,
      last_status: lastStatus,
      consecutive_failures: failed && !sent ? (prev.consecutive_failures || 0) + 1 : 0,
      total_sent: (prev.total_sent || 0) + sent,
    }));
  }
  return { sent, failed };
}

/**
 * One cron tick: send pending alerts, then leave a heartbeat (11 Nov 2026). The health
 * monitor in ctzb-scheduler reads it from the shared NOTIFY namespace: if this Worker's
 * cron stops, setup alerts stop silently, so the heartbeat going stale is itself an alert.
 * One KV write per tick (4 an hour).
 */
async function tick(env, fetchImpl = fetch) {
  let r;
  try { r = await notify(env, fetchImpl); } catch (e) { r = { error: "notify threw" }; }
  if (env.NOTIFY) {
    try { await env.NOTIFY.put("heartbeat", JSON.stringify({ at: Date.now(), result: r })); } catch (_) {}
  }
  return r;
}

async function handle(req, env, fetchImpl = fetch) {
  const refusal = await gate(req, env, fetchImpl);
  if (refusal) return refusal;
  const { pathname } = new URL(req.url);

  // The one write: a test message, so a wrong chat id or an unstarted bot shows up today
  // instead of as a silent failure on the next real alert. Gated like everything else,
  // POST only, at most once per 10 minutes.
  if (pathname === "/alerts/test") {
    if (req.method !== "POST") return deny(405, "POST only");
    if (!env.NOTIFY || !env.TELEGRAM_BOT_TOKEN || !env.TELEGRAM_CHAT_ID) return deny(503, "Alerts not configured");
    const last = +(await env.NOTIFY.get("test:last") || 0);
    if (Date.now() - last < 10 * 60 * 1000) return deny(429, "Test already sent in the last 10 minutes");
    await env.NOTIFY.put("test:last", String(Date.now()));
    const statuses = [];
    for (const chat of recipients(env)) {
      let s = 0;
      try { s = await telegramSend(env, "CTZB alerts are connected. Real alerts arrive here when a low forms, confirms or vanishes.", fetchImpl, chat); } catch (_) {}
      statuses.push(s);
    }
    const status = statuses.every((s) => s === 200) ? 200 : statuses.find((s) => s !== 200);
    // the ids are not echoed back: the count and each recipient's status only
    return new Response(JSON.stringify({ sent: status === 200, telegram_status: status, recipients: statuses.length, statuses }), {
      status: status === 200 ? 200 : 502,
      headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store", ...SEC_HEADERS },
    });
  }
  if (req.method !== "GET" && req.method !== "HEAD") return deny(405, "Read-only");

  if (pathname === "/" || pathname === "/index.html") {
    return new Response(req.method === "HEAD" ? null : PAGE, {
      headers: { "content-type": "text/html; charset=utf-8", "cache-control": "private, no-store",
                 "content-security-policy": PAGE_CSP, ...SEC_HEADERS },
    });
  }
  const m = pathname.match(DATASET);
  if (m) {
    if (!env.MIRROR) return deny(503, "Mirror binding missing");
    // Cards are served only when the feed says the run's checks passed (cards_withheld === false), the same rule the
    // member site follows. Otherwise 503: the page keeps the cards it already has, or says they are held back.
    // cards.csv is written before verify_cards.py runs and committed whatever the outcome (audit round 47, 24 Nov 2026).
    if (m[1] === "cards.csv" && !(await cardsCleared(env))) return deny(503, "Cards held back: the last run's checks did not pass");
    const r = await env.MIRROR.fetch(new Request("https://mirror/datasets/" + m[1]));
    if (!r.ok) return deny(r.status === 404 ? 404 : 502, "Dataset unavailable");
    return new Response(req.method === "HEAD" ? null : r.body, {
      headers: { "content-type": "text/csv; charset=utf-8", "cache-control": "private, no-store",
                 "x-ctzb-stale": r.headers.get("x-ctzb-stale") || "unknown", ...SEC_HEADERS },
    });
  }
  if (pathname === "/health") {
    let mirror = "unreachable";
    try { const r = await env.MIRROR.fetch(new Request("https://mirror/health")); mirror = r.ok ? "ok" : String(r.status); } catch (_) {}
    const ns = env.NOTIFY ? await env.NOTIFY.get("status", { type: "json" }) : null;
    const alerts = { configured: !!(env.NOTIFY && env.TELEGRAM_BOT_TOKEN && env.TELEGRAM_CHAT_ID), ...(ns || {}) };
    return new Response(JSON.stringify({ ok: mirror === "ok", gate: env.GATE_MODE, mirror, alerts }, null, 2), {
      headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store", ...SEC_HEADERS },
    });
  }
  return deny(404, "Not found");
}

export default {
  fetch(req, env) { return handle(req, env); },
  scheduled(event, env, ctx) { ctx.waitUntil(tick(env)); },
};
